"""PSR personal invite links: enrollment QR + HTTPS landing for volunteers."""

from __future__ import annotations

import time
from urllib.parse import urlparse

from flask import Blueprint
from flask import current_app as app
from flask import jsonify, request
from flask_babel import gettext
from flask_security import auth_required, current_user, roles_accepted

from opentakserver.extensions import db, logger
from opentakserver.models.Token import Token
from opentakserver.models.user import User

psr_invite_api = Blueprint("psr_invite_api", __name__)


def _host() -> str:
    return urlparse(request.url_root).hostname or "fts.plasmadancer.ru"


def _invite_url(jwt_token: str) -> str:
    # Public HTTPS page (static) + token in query
    return f"https://{_host()}/downloads/psr-invite.html?t={jwt_token}"


def _qr_string(username: str, jwt_token: str) -> str:
    return f"tak://com.atakmap.app/enroll?host={_host()}&username={username}&token={jwt_token}"


def _ensure_token(username: str, body: dict) -> Token:
    row = db.session.execute(db.session.query(Token).filter_by(username=username)).first()
    token = row[0] if row else None
    if not token:
        token = Token()
        token.creation = int(time.time())
    expiration = body.get("exp")
    if expiration is not None:
        expiration = int(expiration)
        if expiration > 2147483647:
            expiration = expiration / 1000
        token.expiration = expiration
    not_before = body.get("nbf")
    if not_before is not None:
        not_before = int(not_before)
        if not_before > 2147483647:
            not_before = not_before / 1000
        token.not_before = not_before
    if body.get("max"):
        try:
            max_uses = int(body.get("max"))
            if max_uses > 0:
                token.max_uses = max_uses
        except (TypeError, ValueError):
            pass
    token.username = username
    token.disabled = False
    token.hash_token()
    db.session.add(token)
    db.session.commit()
    return token


@psr_invite_api.route("/api/psr/invite", methods=["POST"])
@auth_required()
@roles_accepted("administrator")
def create_invite():
    """Admin: create/refresh enrollment token and return personal HTTPS invite URL."""
    body = request.get_json(silent=True) or {}
    username = (body.get("username") or "").strip()
    if not username:
        return jsonify({"success": False, "error": gettext("username required")}), 400
    user = db.session.query(User).filter_by(username=username).first()
    if not user:
        return jsonify({"success": False, "error": gettext("No such user: %(u)s", u=username)}), 404
    try:
        token = _ensure_token(username, body)
        jwt_tok = token.generate_token()
        hint_password = body.get("password_hint")  # optional plaintext shown once on page via POST body echo only
        return jsonify(
            {
                "success": True,
                "username": username,
                "invite_url": _invite_url(jwt_tok),
                "qr_string": _qr_string(username, jwt_tok),
                "token": jwt_tok,
                "password_hint": hint_password if hint_password else None,
                "ca_password": "atakatak",
                "downloads": {
                    "truststore": f"https://{_host()}/downloads/truststore-root.p12",
                    "atak_config": f"https://{_host()}/downloads/psr-atak-config.zip",
                    "field_kit": f"https://{_host()}/downloads/psr-field-kit.zip",
                    "pss_tak": f"https://{_host()}/downloads/PSS-TAK-latest.apk",
                    "icu": f"https://{_host()}/downloads/OpenTAK_ICU-PSR-latest.apk",
                },
            }
        )
    except Exception as e:
        logger.error("psr invite create failed: %s", e)
        return jsonify({"success": False, "error": str(e)}), 400


@psr_invite_api.route("/api/psr/invite", methods=["GET"])
def resolve_invite():
    """Public: resolve invite JWT without session cookie. Does not increment use count."""
    jwt_tok = (request.args.get("t") or request.args.get("token") or "").strip()
    if not jwt_tok:
        return jsonify({"success": False, "error": gettext("token required")}), 400
    try:
        import jwt as pyjwt
        import os

        pub = os.path.join(
            app.config.get("OTS_CA_FOLDER"), "certs", "opentakserver", "opentakserver.pub"
        )
        with open(pub, "r") as key:
            decoded = pyjwt.decode(
                jwt_tok, key.read(), algorithms=["RS256"], audience="OpenTAKServer"
            )
        username = decoded.get("sub")
        if not username:
            return jsonify({"success": False, "error": gettext("Invalid token")}), 400
        row = db.session.execute(db.session.query(Token).filter_by(username=username)).first()
        token_row = row[0] if row else None
        if not token_row or token_row.disabled:
            return jsonify({"success": False, "error": gettext("Token disabled or missing")}), 404
        return jsonify(
            {
                "success": True,
                "username": username,
                "qr_string": _qr_string(username, jwt_tok),
                "invite_url": _invite_url(jwt_tok),
                "ca_password": "atakatak",
                "hint": "Пароль учётной записи OTS сообщает штаб отдельно (не в ссылке).",
                "server": {
                    "host": _host(),
                    "cot_ssl": 8089,
                    "enrollment": 8446,
                    "rtsp": 8554,
                    "rtsps": 8322,
                },
                "downloads": {
                    "truststore": f"https://{_host()}/downloads/truststore-root.p12",
                    "atak_config": f"https://{_host()}/downloads/psr-atak-config.zip",
                    "field_kit": f"https://{_host()}/downloads/psr-field-kit.zip",
                    "pss_tak": f"https://{_host()}/downloads/PSS-TAK-latest.apk",
                    "icu": f"https://{_host()}/downloads/OpenTAK_ICU-PSR-latest.apk",
                    "connect_txt": f"https://{_host()}/downloads/psr-connect.txt",
                },
            }
        )
    except Exception as e:
        logger.error("psr invite resolve failed: %s", e)
        return jsonify({"success": False, "error": gettext("Invalid or expired token")}), 400
